import{_ as a,o as n,c as e,S as p}from"./chunks/framework.D1Ss-Xl7.js";const m=JSON.parse('{"title":"Git 提交规范","description":"","frontmatter":{"title":"Git 提交规范","date":"2022-07-23 20:37","comments":true,"archives":2022,"tags":["github"]},"headers":[],"relativePath":"posts/2022-07-23-git-commit-lint/index.md","filePath":"posts/2022/2022-07-23-git-commit-lint.md"}'),l={name:"posts/2022-07-23-git-commit-lint/index.md"};function i(r,s,t,o,c,d){return n(),e("div",null,[...s[0]||(s[0]=[p(`<p>良好的代码风格很重要，但是良好的 commit 记录同样重要。我们提交代码的时候都要提交 commit message，否则就不允许提交。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">$</span><span style="color:#032F62;"> git</span><span style="color:#032F62;"> commit</span><span style="color:#005CC5;"> -m</span><span style="color:#032F62;"> &quot;hello world&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="commit-message-格式" tabindex="-1">commit message 格式 <a class="header-anchor" href="#commit-message-格式" aria-label="Permalink to &quot;commit message 格式&quot;">​</a></h2><p>目前最流行的提交规范是<a href="https://www.conventionalcommits.org/en/v1.0.0/" target="_blank" rel="noreferrer">Conventional Commits</a>，格式如下：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;[optional scope]: &lt;description&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[optional body]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[optional footer(s)]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="header" tabindex="-1">Header <a class="header-anchor" href="#header" aria-label="Permalink to &quot;Header&quot;">​</a></h3><p>Header 有三个字段，type(必须)，scope(可选) 和 description(必须)。</p><p>type 用于说明 commit 的类别，有以下几个选项：build, chore, ci, docs, feat, fix, perf, refactor, revert, style, test</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>build: 对构建系统或者外部依赖项进行了修改</span></span>
<span class="line"><span>chore: 构建过程或辅助工具的变动</span></span>
<span class="line"><span>ci: 对CI配置文件或脚本进行了修改</span></span>
<span class="line"><span>docs: 对文档进行了修改</span></span>
<span class="line"><span>feat: 增加新功能</span></span>
<span class="line"><span>fix: 修复BUG</span></span>
<span class="line"><span>perf: 优化相关，比如提升性能，体验</span></span>
<span class="line"><span>refactor: 重构代码</span></span>
<span class="line"><span>revert: 回滚到上一个版本</span></span>
<span class="line"><span>style: 修改代码格式</span></span>
<span class="line"><span>test: 添加测试代码</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>scope 用于说明 commit 影响的范围，比如某个组件的修改。</p><p>description 是 commit 目的的简短描述，不超过 50 个字符。最好以动词开头，首字母小写，末尾不加句号(.)</p><h3 id="body" tabindex="-1">Body <a class="header-anchor" href="#body" aria-label="Permalink to &quot;Body&quot;">​</a></h3><p>Body 是可选的，用来对本次提交进行详细描述， 可以写成多行，例如：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>fix: prevent racing of requests</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Introduce a request id and a reference to latest request. Dismiss</span></span>
<span class="line"><span>incoming responses other than from latest request.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="footer" tabindex="-1">Footer <a class="header-anchor" href="#footer" aria-label="Permalink to &quot;Footer&quot;">​</a></h3><p>Footer 也是可选的，主要有两个使用情况。一种是不兼容性更新：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>chore!: drop support for Node 6</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BREAKING CHANGE: use JavaScript features not available in Node 6.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>一种是引用提交的问题，例如本次提交是修正某个 Issue 的问题。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>feat(lang): add Polish language</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Closes #234</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>良好的 commit 提交规范和代码规范同样重要。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://www.ruanyifeng.com/blog/2016/01/commit_message_change_log.html" target="_blank" rel="noreferrer">Commit message 和 Change log 编写指南</a></p>`,23)])])}const u=a(l,[["render",i]]);export{m as __pageData,u as default};
